function onlineEvent(data: { payload: { event: TwitchOnlineEvent } }) {
  try {
    const {
      payload: { event },
    } = data
    logger.info(`${event.broadcaster_user_id} just went online`)
    onlineEvents.set(event.broadcaster_user_id, new Date())
  } catch (error) {
    logger.error('Error in onlineEvent initial processing', {
      error: error instanceof Error ? error.message : String(error),
      eventData: JSON.stringify(data),
    })
  }

  async function handler() {
    try {
      const { data: user, error: userError } = await supabase
        .from('accounts')
        .select('userId')
        .eq('provider', 'twitch')
        .eq('providerAccountId', data?.payload?.event.broadcaster_user_id)
        .single()

      if (userError) {
        logger.error('Failed to fetch user account', {
          error: userError.message,
          twitchId: data?.payload?.event.broadcaster_user_id,
        })
        return
      }

      if (user?.userId) {
        const { error: updateError } = await supabase
          .from('users')
          .update({
            stream_online: true,
            stream_start_date: data?.payload?.event.started_at,
            updated_at: new Date().toISOString(),
          })
          .eq('id', user.userId)

        if (updateError) {
          logger.error('Failed to update user online status', {
            error: updateError.message,
            twitchId: data?.payload?.event.broadcaster_user_id,
            userId: user.userId,
          })
          return
        }

        logger.info('updated online event', { twitchId: data?.payload?.event.broadcaster_user_id })
      } else {
        logger.warn('No user found for Twitch account', {
          twitchId: data?.payload?.event.broadcaster_user_id,
        })
      }
    } catch (error) {
      logger.error('Unexpected error in online event handler', {
        error: error instanceof Error ? error.message : String(error),
        twitchId: data,
      })
    }
  }

  void handler()
}

async (socket) => {
    logger.info('[TWITCHEVENTS] Joining socket to room')
    await socket.join(DOTABOD_EVENTS_ROOM)

    // Track liveness by connected-client count so a reconnecting client's old
    // socket disconnecting can't strand the flag false while a new one is live.
    connectedClients.add(socket.id)
    eventsIOConnected = true
    logger.info('[TWITCHEVENTS] client connected', { clients: connectedClients.size })

    socket.on('disconnect', () => {
      connectedClients.delete(socket.id)
      eventsIOConnected = connectedClients.size > 0
      logger.info('[TWITCHEVENTS] Socket disconnected', { clients: connectedClients.size })
    })

    socket.on('getVersion', (ack: (commitHash: string | null) => void) => {
      ack(process.env.COMMIT_HASH ?? null)
    })

    // Handle conduit data requests from twitch-chat
    socket.on('getConduitData', (options = { forceRefresh: false }) => {
      void sendConduitData(socket, options.forceRefresh)
    })

    socket.on('grant', (providerAccountId: string) => {
      logger.info('[TWITCHEVENTS] Granting events for user', { providerAccountId })
      if (providerAccountId === process.env.TWITCH_BOT_PROVIDERID) {
        logger.info('Bot was granted in twitch-events!')
        botStatus.isBanned = false
      }
    })

    socket.on('revoke', (providerAccountId: string) => {
      void revokeEvent({ providerAccountId })
    })

    socket.on('enable', (providerAccountId: string) => {
      onSocketEnable(providerAccountId)
    })

    socket.on('resubscribe', (providerAccountId: string) => {
      onSocketResubscribe(providerAccountId)
    })
  }

