  const kills = monotonic(gsi?.player?.kills, cached?.kills)
  const deaths = monotonic(gsi?.player?.deaths, cached?.deaths)
  const assists = monotonic(gsi?.player?.assists, cached?.assists)
  const radiant_score = monotonic(gsi?.map?.radiant_score, cached?.radiant_score)
  const dire_score = monotonic(gsi?.map?.dire_score, cached?.dire_score)
  const duration = monotonic(gsi?.map?.game_time, cached?.duration)

  const iso = now.toISOString()
  return {
    created_at: iso,
    dire_score,
    hero_name,
    kda: { assists, deaths, duration, kills },
    matchId,
    radiant_score,
    updated_at: iso,
  }
}

async function checkAltAccount(
  channel: string,
  chattersUsername: string,
  twitchChannelId: string,
  userInfo: { userId: string },
  messageId: string,
  client: SocketClient
) {
  // If already cached as not an alt account, skip
  if (!altAccountCache[chattersUsername]) {
    return
  }

  // If cached as alt account, check cooldown before sending message
  if (altAccountCache[chattersUsername]) {
    const now = Date.now()
    const lastTime = lastAltAccountMessageTimestamps[chattersUsername] || 0
    if (now - lastTime < ALT_ACCOUNT_COOLDOWN_MS) {
      return
    }

    if (speak) {
      chatClient.say(
        channel,
        t('altAccount', {
          emote: 'hesRight',
          emote2: 'PepeMods',
          lng: client.locale || 'en',
          name: chattersUsername,
        }),
        messageId
      )
    }
    lastAltAccountMessageTimestamps[chattersUsername] = now
    return
  }

  // Not cached, perform the check
  try {
    const api = await getTwitchAPI(twitchChannelId)
    const userData = await api.users.getUserByName(chattersUsername)
    if (!userData) {
      altAccountCache[chattersUsername] = false
      return
    }

    const accountCreationDate = userData.creationDate
    const {
      data: [follow],
    } = await api.channels.getChannelFollowers(twitchChannelId, userInfo.userId)
    if (!follow) {
      altAccountCache[chattersUsername] = false
      return
    }

    const followageDate = follow.followDate
    const timeDifference = followageDate.getTime() - accountCreationDate.getTime()
    const daysDifference = Math.ceil(timeDifference / (1000 * 3600 * 24))
    const isAlt = daysDifference >= 0 && daysDifference < 10

    altAccountCache[chattersUsername] = isAlt

    if (isAlt) {
      const now = Date.now()
      const lastTime = lastAltAccountMessageTimestamps[chattersUsername] || 0
      if (now - lastTime >= ALT_ACCOUNT_COOLDOWN_MS) {
        if (speak) {
          chatClient.say(
            channel,
            t('altAccount', {
              emote: 'hesRight',
              emote2: 'PepeMods',
              lng: client.locale || 'en',
              name: chattersUsername,
            }),
            messageId
          )
        }
        lastAltAccountMessageTimestamps[chattersUsername] = now
      }
    }
  } catch (error) {
    logger.error('Error checking alt account', { channel, error, user: chattersUsername })
    altAccountCache[chattersUsername] = false // Don't retry on error
  }
}

