  statusCalls: number[]
  jsonCalls: unknown[]
} {
  const statusCalls: number[] = []
  const jsonCalls: unknown[] = []
  const response = {
    json(value: unknown) {
      jsonCalls.push(value)
      return response
    },
    status(code: number) {
