new Promise<DelayedGames>((resolve, _reject) => {
    operation.attempt(async (currentAttempt) => {
      let game: DelayedGames
      try {
        const apiUrl = getApiUrl(steam_server_id)
        const response = await fetch(apiUrl)

        // 400 is a bad request, but it's not rate limited and it means the next request after it should work
        // Handle rate limiting (403/429)
        if (response.status === 403 || response.status === 429) {
          logger.warn(`[STEAM] Rate limited with ${response.status} response. Backing off...`)
          // Exponential backoff with longer delay for rate limiting
          const backoffDelay = Math.min(30_000, 5000 * 2 ** (currentAttempt - 1))

          // Keep the request in the activeRequests map during the backoff period
          // to prevent multiple requests to the same rate-limited endpoint
          const rateLimitError = new Error(`Rate limited with ${response.status}`)

          // Set a timeout to retry after the backoff period
          setTimeout(() => {
            operation.retry(rateLimitError)
          }, backoffDelay)

          return // Don't immediately retry, wait for the timeout
        }

        if (!response.ok) {
          throw new Error(`HTTP error! Status: ${response.status}`)
        }
        game = (await response.json()) as DelayedGames
      } catch (error) {
        if (error instanceof Error && error.message.includes('400')) {
          // Don't log 400 errors as they're expected and the next request should work
          return operation.retry(new Error('Match not found'))
        }
        logger.error('[STEAM] Failed to fetch game data:', { error })
        return operation.retry(new Error('Match not found'))
      }
      const { hasAccountIds, hasHeroes } = hasSteamData(game)
      // needs account ids
      const retryAttempt = !hasAccountIds || !game ? new Error() : undefined
      if (operation.retry(retryAttempt)) {
        return
      }

      // needs hero data
      const retryAttempt2 = waitForHeros && !hasHeroes ? new Error() : undefined
      if (operation.retry(retryAttempt2)) {
        return
      }

      // 2-minute delay gives "0" match id, so we use the gsi match id instead
      game.match.match_id = match_id
      game.match.server_steam_id = steam_server_id
      const gamePlusMore = { ...game, createdAt: new Date() }

      if (hasHeroes) {
        // sort players by team_slot
        sortPlayersBySlot(game)

        if (process.env.DOTABOD_ENV === 'production') {
          await saveMatch({ game: gamePlusMore, match_id })
        }

        if (!forceRefetchAll) {
          // forward the msg to dota node app
          getSocketIoServer().to('steam').emit('saveHeroesForMatchId', { matchId: match_id, token })
        }

        // Remove from active requests before resolving
        activeRequests.delete(match_id)
        resolve(gamePlusMore)
        return
      }

      if (!waitForHeros) {
        // sort players by team_slot
        sortPlayersBySlot(game)

        await saveMatch({ game: gamePlusMore, match_id, refetchCards })
        waitForHeros = true
        operation.retry(new Error())
      }

      // Remove from active requests before resolving
      activeRequests.delete(match_id)
      resolve(gamePlusMore)
    })
  })

async function closeTwitchBetById(
  won: boolean,
  twitchId: string,
  predictionId: string,
  matchId: string
): Promise<boolean> {
  try {
    const api = await getTwitchAPI(twitchId)

    // Fetch recent predictions and find the one matching our ID
    // We fetch more than 1 since the current game might have a different prediction
    const { data: predictions } = await retryTransient(
      () => api.predictions.getPredictions(twitchId, { limit: 10 }),
      { label: 'resolveMatch:getPredictions' }
    )

    if (!Array.isArray(predictions) || !predictions.length) {
      logger.info('[BETS] Retroactive resolution - no predictions found', {
        matchId,
        predictionId,
        twitchId,
      })
      return false
    }

    // Find the specific prediction by ID
    const prediction = predictions.find((p) => p.id === predictionId)

    if (!prediction) {
      logger.info('[BETS] Retroactive resolution - specific prediction not found in recent list', {
        availablePredictions: predictions.map((p) => ({ id: p.id, status: p.status })),
        matchId,
        predictionId,
        twitchId,
      })
      return false
    }

    // Check if prediction is in a state that can be resolved
    // ACTIVE or LOCKED predictions can be resolved
    if (!['ACTIVE', 'LOCKED'].includes(prediction.status)) {
      logger.info('[BETS] Retroactive resolution - prediction already resolved or canceled', {
        matchId,
        predictionId,
        status: prediction.status,
        twitchId,
      })
      return false
    }

    const [wonOutcome, lossOutcome] = prediction.outcomes

    await retryTransient(
      () =>
        api.predictions.resolvePrediction(
          twitchId,
          predictionId,
          won ? wonOutcome.id : lossOutcome.id
        ),
      { label: 'resolveMatch:resolvePrediction' }
    )

    logger.info('[BETS] Retroactive resolution - prediction resolved successfully', {
      matchId,
      predictionId,
      twitchId,
      won,
    })

    return true
  } catch (error) {
    logger.info('[BETS] Retroactive resolution - could not resolve prediction', {
      error,
      matchId,
      predictionId,
      twitchId,
    })
    return false
  }
}

