async function hydrateInvalidTokensFromRedis(
  cache: InvalidTokensCache,
  client: RedisScanLike
): Promise<number> {
  // Gate on isReady: if the connection isn't up we can't scan. The caller
  // (setupRedisClient) currently awaits connectClient() before invoking us,
  // but future call sites might not.
  if (client.isReady === false) {
    logger.error('[USER] invalidTokens hydrate skipped: redis not ready')
    return 0
  }
  let count = 0
  try {
    for await (const key of client.scanIterator({
      COUNT: 500,
      MATCH: `${REDIS_KEY_PREFIX}*`,
    })) {
      const token = key.slice(REDIS_KEY_PREFIX.length)
      if (token && !cache.has(token)) {
        cache.hydrate(token)
        count++
      }
    }
  } catch (error) {
    // Real boot failure — alert.
    logger.error('[USER] invalidTokens hydrate Redis scan failed', { error })
  }
  return count
}

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry)
    if (statSync(p).isDirectory()) {
      // CLI-only entries live under src/scripts/ and are never bundled.
      if (entry === 'scripts' || entry === '__tests__') {
        continue
      }
      walk(p, out)
    } else if (entry.endsWith('.ts')) {
      out.push(p)
    }
  }
  return out
}

async function getAccountIds(): Promise<string[]> {
  logger.info('[TWITCHSETUP] Running getAccountIds')

  const providerIds: string[] = []
  let from = 0

  while (true) {
    const { data, error } = await supabase
      .from('accounts')
      .select('providerAccountId, users!inner(followers)')
      .eq('provider', 'twitch')
      .neq('requires_refresh', true)
      .ilike('scope', '%channel:bot%')
      .order('followers', { ascending: false, nullsFirst: false, referencedTable: 'users' })
      .order('providerAccountId', { ascending: true })
      .range(from, from + PAGE_SIZE - 1)

    if (error) {
      logger.error('[TWITCHEVENTS] getAccountIds query failed', { error: error.message })
      throw error
    }

    providerIds.push(...pluckProviderIds(data as AccountRow[] | null))

    if (!data || data.length < PAGE_SIZE) {
      break
    }
    from += PAGE_SIZE
  }

  if (providerIds.length < 10) {
    logger.info(`[TWITCHEVENTS] joining ${providerIds.length} channels`, { providerIds })
  }
  logger.info(`[TWITCHEVENTS] joining ${providerIds.length} channels`)
  return providerIds
}

function splitIntoMessages(parts: string[], separator: string, limit: number): string[] {
  const messages: string[] = []
  let current = ''

  for (const part of parts) {
    const wouldBe = current ? `${current}${separator}${part}` : part
    if (wouldBe.length <= limit) {
      current = wouldBe
    } else {
      if (current) {
        messages.push(current)
      }
      current = part
    }
  }

  if (current) {
    messages.push(current)
  }
  return messages
}

