function formatUnresolvedMatch(match: UnresolvedMatch, now: Date = new Date()): string {
  const hero = getHero(match.hero_name as HeroNames)
  const heroName = hero?.localized_name ?? match.hero_name ?? 'Unknown'

  const parts: string[] = [heroName]

  const { kda } = match
  if (kda && (kda.kills != null || kda.deaths != null || kda.assists != null)) {
    parts.push(`${kda.kills ?? 0}/${kda.deaths ?? 0}/${kda.assists ?? 0}`)
  }

  if (match.radiant_score != null && match.dire_score != null) {
    parts.push(`${match.radiant_score}-${match.dire_score}`)
  }

  if (kda?.duration != null) {
    parts.push(formatDuration(kda.duration))
  }

  const endedAt = match.updated_at || match.created_at
  if (endedAt) {
    const ago = formatTimeAgo(new Date(endedAt), now)
    if (ago) {
      parts.push(`~${ago}`)
    }
  }

  return `${match.matchId} (${parts.join(', ')})`
}

function fakeApi(opts: {
  clipIds: string[]
  durations: Record<string, number>
  createThrowsOn?: number[]
}) {
  let createCalls = 0
  const getCalls: string[] = []
  // Clip creation goes through `callApi` rather than `clips.createClip` because
  // Twurple can't send Twitch's `duration` parameter; capture the queries so tests
  // can assert what was actually requested.
  const createQueries: Record<string, string>[] = []
  const api = {
    callApi: async ({ query }: { query: Record<string, string> }) => {
      createCalls += 1
      createQueries.push(query)
      if (opts.createThrowsOn?.includes(createCalls)) {
        throw new Error('createClip boom')
      }
      const id = opts.clipIds[createCalls - 1]
      if (id === undefined) {
        throw new Error('ran out of fake clip ids')
      }
      return { data: [{ id }] }
    },
    clips: {
      getClipById: async (id: string) => {
        getCalls.push(id)
        const duration = opts.durations[id] ?? 0
        return { duration }
      },
    },
  }
  return {
    api: api as any,
    createQueries,
    getCreateCalls: () => createCalls,
    getGetCalls: () => getCalls,
  }
}

