function isRefreshTokenExpired(token: string): boolean {
  try {
    const [, payload] = token.split('.')
    if (!payload) {
      return false
    }
    const claims = JSON.parse(Buffer.from(payload, 'base64url').toString('utf-8')) as {
      exp?: number
    }
    if (!claims.exp) {
      return false
    }
    // Treat tokens within 1h of expiry as expired to avoid mid-session lapses.
    return claims.exp * 1000 < Date.now() + 60 * 60 * 1000
  } catch {
    return false
  }
}

step(event: GcEvent): GcAction {
    const t = this.now()

    switch (event.type) {
      case 'gcReady': {
        this.ready = true
        this.notReadySince = undefined
        this.lastRelaunchAt = undefined
        return { type: 'noop' }
      }

      case 'loggedOn': {
        // CM is up but GC isn't ready yet; ensure the not-ready clock is running
        // so a logon that never reaches GC-ready still escalates.
        if (!this.ready && this.notReadySince === undefined) {
          this.notReadySince = t
        }
        return { type: 'noop' }
      }

      case 'gcUnready':
      case 'disconnected':
      case 'helloTimeout': {
        // These all mean the GC is not usable: flip out of ready and start (or
        // keep) the not-ready clock, then evaluate the ladder.
        this.ready = false
        if (this.notReadySince === undefined) {
          this.notReadySince = t
        }
        return this.evaluateNotReady(t)
      }

      case 'tick': {
        // Neutral heartbeat: only escalates an already-not-ready state, never
        // manufactures one while healthy.
        if (this.ready) {
          return { type: 'noop' }
        }
        return this.evaluateNotReady(t)
      }
    }
  }

