function processFile(filePath: string): void {
  if (processedFiles.has(filePath)) {
    return
  }
  processedFiles.add(filePath)

  // Skip non-source files
  const ext = extname(filePath)
  if (!extensions.has(ext)) {
    return
  }

  const imports = extractImports(filePath)
  const fileDeps = new Set<string>()
  dependencies.set(filePath, fileDeps)

  for (const importPath of imports) {
    if (!isInternalModule(importPath)) {
      // Skip external modules
      if (externalModules.has(importPath)) {
        continue
      }

      // Skip node built-ins and other external packages
      if (!importPath.startsWith('@dotabod/')) {
        continue
      }
    }

    const resolvedImport = resolveImport(importPath, filePath)
    if (resolvedImport) {
      fileDeps.add(resolvedImport)
      // Recursively process this import if we haven't already
      processFile(resolvedImport)
    }
  }
}

async function chatterMatchFound(client: SocketClient) {
  if (!client.stream_online) {
    return
  }

  const commands = DelayedCommands.filter((cmd) =>
    getValueOrDefault(cmd.key, client.settings, client.subscription)
  )

  if (commands.length) {
    say(
      client,
      t('matchFound', {
        commandList: commands.map((c) => c.command).join(' · '),
        lng: client.locale,
      }),
      {
        chattersKey: 'commandsReady',
        delay: false,
      }
    )
  }

  try {
    // Send auto commands if enabled
    const autoCommands = getValueOrDefault(
      DBSettings.autoCommandsOnMatchStart,
      client.settings,
      client.subscription
    ) as string[]

    logger.info('[AUTO_COMMANDS] Processing auto commands', {
      autoCommands,
      hasCommands: autoCommands && autoCommands.length > 0,
      token: client.token,
    })

    if (autoCommands && autoCommands.length > 0) {
      for (const commandKey of autoCommands) {
        // Find the command in DelayedCommands that matches this key
        const commandInfo = DelayedCommands.find((cmd) => cmd.key === commandKey)

        if (commandInfo) {
          logger.info('[AUTO_COMMANDS] Executing auto command', {
            command: commandInfo.command,
            commandKey,
            token: client.token,
          })

          // Simulate a command message
          await commandHandler
            .handleMessage({
              channel: {
                client,
                id: client.Account?.providerAccountId || '',
                name: client.name.startsWith('#') ? client.name : `#${client.name}`,
                settings: client.settings,
              },
              content: commandInfo.command,
              user: {
                messageId: '',
                name: client.name,
                permission: 3, // Broadcaster permission
                userId: client.Account?.providerAccountId || '',
              },
            })
            .catch((error: unknown) => {
              logger.error('[AUTO_COMMANDS] Error executing auto command', {
                command: commandInfo.command,
                commandKey,
                error,
              })
            })

          logger.info('[AUTO_COMMANDS] Successfully executed auto command', {
            command: commandInfo.command,
            commandKey,
          })

          // Small delay between commands to prevent rate limiting
          await new Promise((resolve) => setTimeout(resolve, 100))
        } else {
          logger.warn('[AUTO_COMMANDS] Command not found in DelayedCommands', {
            commandKey,
            token: client.token,
          })
        }
      }
    }
  } catch (error) {
    logger.error('[AUTO_COMMANDS] Error sending auto commands', { error })
  }
}

async function handleUserOnlineMessages(userId: string, username: string) {
  try {
    const now = new Date().toISOString()
    const processedMessages: typeof userSpecificMessages = []

    // Find scheduled messages for this specific user that are pending and due to be sent
    const { data: userSpecificMessages, error: userMessagesError } = await supabase
      .from('ScheduledMessage')
      .select('*')
      .eq('userId', userId)
      .lte('sendAt', now)
      .eq('status', 'PENDING')

    if (userMessagesError) {
      logger.error('Error fetching user-specific scheduled messages:', userMessagesError)
      return []
    }

    // Find scheduled messages for all users that are pending and due to be sent
    const { data: globalMessages, error: globalMessagesError } = await supabase
      .from('ScheduledMessage')
      .select('*')
      .eq('isForAllUsers', true)
      .lte('sendAt', now)
      .eq('status', 'PENDING')

    if (globalMessagesError) {
      logger.error('Error fetching global scheduled messages:', globalMessagesError)
      return []
    }

    const allMessages = [...(userSpecificMessages || []), ...(globalMessages || [])]

    if (allMessages.length === 0) {
      return []
    }

    logger.info(`Processing ${allMessages.length} scheduled messages for user ${userId}`)

    for (const message of allMessages) {
      // Check if this message has already been delivered to this user
      const { data: existingDelivery, error: deliveryError } = await supabase
        .from('MessageDelivery')
        .select('*')
        .eq('scheduledMessageId', message.id)
        .eq('userId', userId)
        .single()

      if (deliveryError && deliveryError.code !== 'PGRST116') {
        // PGRST116 is "no rows returned" error
        logger.error('Error checking existing delivery:', deliveryError)
        continue
      }

      // Skip if already delivered
      if (existingDelivery) {
        continue
      }

      // Send the message to the user
      const messageSent = await sendMessageToUser(userId, username, message.message)

      if (!messageSent) {
        logger.error(`Failed to send message ${message.id} to user ${userId}`)
        continue
      }

      const now = new Date().toISOString()

      // Create a delivery record
      const { error: createDeliveryError } = await supabase.from('MessageDelivery').insert({
        createdAt: now,
        deliveredAt: now,
        scheduledMessageId: message.id,
        status: 'DELIVERED',
        updatedAt: now,
        userId,
      })

      if (createDeliveryError) {
        logger.error('Error creating delivery record:', createDeliveryError)
        continue
      }

      // For user-specific messages, mark the message as delivered
      if (message.isForAllUsers) {
        // For global messages, check if all users have received it
        const { count: userCount, error: userCountError } = await supabase
          .from('users')
          .select('*', { count: 'exact', head: true })

        if (userCountError) {
          logger.error('Error counting users:', userCountError)
          continue
        }

        const { count: deliveryCount, error: deliveryCountError } = await supabase
          .from('MessageDelivery')
          .select('*', { count: 'exact', head: true })
          .eq('scheduledMessageId', message.id)
          .eq('status', 'DELIVERED')

        if (deliveryCountError) {
          logger.error('Error counting deliveries:', deliveryCountError)
          continue
        }

        // If all users have received it, mark as delivered
        if (deliveryCount && userCount && deliveryCount >= userCount) {
          const { error: updateError } = await supabase
            .from('ScheduledMessage')
            .update({
              status: 'DELIVERED',
              updatedAt: new Date().toISOString(),
            })
            .eq('id', message.id)

          if (updateError) {
            logger.error('Error updating global message status:', updateError)
          }
        }
      } else {
        const { error: updateError } = await supabase
          .from('ScheduledMessage')
          .update({
            status: 'DELIVERED',
            updatedAt: new Date().toISOString(),
          })
          .eq('id', message.id)

        if (updateError) {
          logger.error('Error updating message status:', updateError)
        }
      }

      processedMessages.push(message)
    }

    return processedMessages
  } catch (error) {
    logger.error('Error handling scheduled messages:', error)
    return []
  }
}

