function isSafeText(text: string): boolean {
  // Convert to lowercase for case-insensitive matching
  const lower = text.toLowerCase()

  // Check if text is in the whitelist (exact match)
  if (SAFE_WORDS_WHITELIST.some((word) => lower.includes(word.toLowerCase()))) {
    return true
  }

  // Special case for 'fakejoker' which is getting false positives
  if (lower === 'fakejoker') {
    return true
  }

  // Check if text only contains whitelisted words
  const words = lower.split(/\s+/)
  const allWordsAreSafe = words.every((word) => {
    // Remove any punctuation before checking
    const cleanWord = word.replaceAll(/[.,?!;:'"()[\]{}]/g, '')
    return cleanWord.length === 0 || SAFE_WORDS_WHITELIST.includes(cleanWord)
  })

  return allWordsAreSafe
}

async function findResolvedMatchesInSession(
  userId: string,
  streamStartDate: Date | null,
  opts: { limit: number; excludeMatchId?: string } = { limit: 5 }
): Promise<ResolvedMatchRow[]> {
  const startDate = getSessionStartDate(streamStartDate)

  let query = supabase
    .from('matches')
    .select('matchId, hero_name, won')
    .eq('userId', userId)
    .not('won', 'is', null)
    .gte('created_at', startDate.toISOString())

  if (opts.excludeMatchId) {
    query = query.neq('matchId', opts.excludeMatchId)
  }

  const { data, error } = await query.order('created_at', { ascending: false }).limit(opts.limit)

  if (error) {
    logger.warn('[BETS] findResolvedMatchesInSession query failed', { error, userId })
    return []
  }

  return (data ?? []) as ResolvedMatchRow[]
}

