    // Additional variants for common transphobic phrases
    /m[e3]n\s*[i1]n\s*dr[e3][s5][s5][e3][s5]/i,
    /b[i1][o0]l[o0]g[i1]c[a@]l\s*[s5][e3]x\s*c[a@]n'?t\s*ch[a@]ng[e3]/i,
