    /g[e3]nd[e3]r\s*dy[s5]ph[o0]r[i1][a@]\s*[i1][s5]n'?t\s*r[e3][a@]l/i,
    /[i1]'?m\s*tr[a@]n[s5]ph[o0]b[i1]c/i,
