            newObj.scope !== oldObj.scope ||
            (newObj.requires_refresh === false && oldObj.requires_refresh === true) ||
            newObj.access_token !== oldObj.access_token
          ) {
            const client = findUser(newObj.userId)
            if (client?.Account) {
              client.Account.scope = newObj.scope
              client.Account.access_token = newObj.access_token
              client.Account.refresh_token = newObj.refresh_token
              client.Account.expires_at = newObj.expires_at
              client.Account.expires_in = newObj.expires_in
              client.Account.obtainment_timestamp = new Date(newObj.obtainment_timestamp ?? '')
              const twitchId = newObj.providerAccountId
              const authProvider = getAuthProvider()
              authProvider.removeUser(twitchId)
              getTwitchAPI(twitchId).catch((error) => {
                logger.error('[TWITCHAPI] Error updating twurple token', {
                  error,
                  twitchId,
                })
              })
            }
          }

          // The frontend will set it to false when they relogin
          // Which allows us to update the authProvider object
          if (newObj.requires_refresh === false && oldObj.requires_refresh === true) {
            invalidTokens.delete(newObj.userId)
            if (newObj.providerAccountId) {
              invalidTokens.delete(newObj.providerAccountId)
            }
            logger.info('[WATCHER ACCOUNT] Refreshing account', {
              twitchId: newObj.providerAccountId,
            })

            const client = findUser(newObj.userId)
            if (client) {
              await clearCacheForUser(client)
            }
          }
        }
      )
      .on

function toggleDotabod(token: string, isBotDisabled: boolean, channel: string, lng = 'en') {
  // Check if we recently sent a toggle message for this user to prevent duplicates
  const cacheKey = `${token}:${channel}`
  const cached = toggleMessageCache.get(cacheKey)
  const now = Date.now()

  if (
    cached &&
    now - cached.timestamp < TOGGLE_MESSAGE_COOLDOWN &&
    cached.disabled === isBotDisabled
  ) {
    logger.info('[TOGGLE] Skipping duplicate toggle message', { channel, isBotDisabled, token })
    return
  }

  const gsiHandler = gsiHandlers.get(token)
  const hasHandler = gsiHandlers.has(token)

  if (!hasHandler) {
    logger.info('[GSI] Could not find client', { channel, token })
    return
  }

  if (isBotDisabled) {
    logger.info('[GSI] Disabling client', { channel, token })
    gsiHandler?.disable()
  } else {
    logger.info('[GSI] Enabling client', { channel, token })
    twitchEvent.emit('enable', gsiHandler?.getChannelId())
    gsiHandler?.enable()
  }

  // Update cache before sending message
  toggleMessageCache.set(cacheKey, { disabled: isBotDisabled, timestamp: now })

  chatClient.say(
    channel,
    t('toggle', { context: isBotDisabled ? 'disabled' : 'enabled', lng }),
    undefined,
    true
  )
}

