function cleanupAccountSharingLogCache() {
  const now = Date.now()
  for (const [key, timestamp] of accountSharingLogCache.entries()) {
    if (now - timestamp > ACCOUNT_SHARING_LOG_INTERVAL * 2) {
      accountSharingLogCache.delete(key)
    }
  }
  // Run cleanup every 10 minutes
  setTimeout(cleanupAccountSharingLogCache, 600_000)
}

function emitRoshEvent(res: RoshRes, token: string, client: SocketClient) {
  if (!res?.minDate) {
    return
  }
  res = getNewRoshTime(res)

  // Only check settings if client is provided
  if (!client) {
    return
  }

  const tellChatRosh = getValueOrDefault(DBSettings.rosh, client.settings, client.subscription)
  if (!tellChatRosh) {
    return
  }

  server.io.to(token).emit('roshan-killed', res)
}

function makeScannerClient(keys: string[], opts: { throws?: boolean } = {}) {
