function ensureIndex() {
  if (known !== null) {
    return
  }
  known = new Set<string>()
  for (const n of events.eventNames() as string[]) {
    known.add(n)
    let acc = ''
    for (const part of n.split(':')) {
      acc = acc ? `${acc}:${part}` : part
      known.add(acc)
    }
  }
}

