async function getRankDetail(mmr: string | number, steam32Id?: number | null) {
  const mmrNum = Number(mmr)

  if (!mmrNum || mmrNum < 0) {
    return null
  }

  // At or higher than max mmr? Lets check leaderboards
  const highestRank = ranks.at(-1)
  if (!highestRank) {
    return null
  }
  if (mmrNum >= highestRank.range[1]) {
    return await lookupLeaderRank(mmrNum, steam32Id)
  }

  const [myRank, nextRank] = ranks.filter((rank) => mmrNum <= rank.range[1])

  // Its not always truthy, nextRank can be beyond the range
  const nextMMR = nextRank?.range[0] || myRank?.range[1]
  const mmrToNextRank = nextMMR - mmrNum
  const winsToNextRank = Math.ceil(mmrToNextRank / MULTIPLIER_SOLO)

  return {
    mmr: mmrNum,
    mmrToNextRank,
    myRank,
    nextMMR,
    nextRank,
    winsToNextRank,
  }
}

function correctSelfHeroWithGsi(heroes: VisionApiHero[], selfHeroId: number | undefined) {
  if (!selfHeroId || selfHeroId <= 0) {
    return heroes
  }
  if (heroes.some((h) => h.hero_id === selfHeroId)) {
    return heroes
  }

  let weakest = 0
  for (let i = 1; i < heroes.length; i++) {
    if ((heroes[i].match_score ?? 1) < (heroes[weakest].match_score ?? 1)) {
      weakest = i
    }
  }
  return heroes.map((h, i) => (i === weakest ? { ...h, hero_id: selfHeroId } : h))
}

