async function checkMidasIterator(client: SocketClient) {
  const { token, gsi: data } = client

  // Find the midas in player's inventory
  const midasItem = findItem({ data, itemName: 'item_hand_of_midas', searchStashAlso: true })

  // Check if player has a midas. findItem returns `Item[] | false`, so an
  // optional-chain shortcut here would skip narrowing on the `false` arm.
  if (!midasItem || !midasItem[0]) {
    return false
  }

  // Get passive midas data from Redis
  const passiveMidasData = (await redisClient.getJson<PassiveMidasData>(
    `${token}:passiveMidas`
  )) || {
    firstNoticedPassive: 0,
    told: 0,
  }

  const midasCharges = Number(midasItem[0].charges)
  const currentTime = Date.now()
  const passiveMidasThreshold = 10_000

  // Hand of Midas has 2 charges since patch 7.38. Both charges full means player is not using it.
  if (midasCharges === 2 && !passiveMidasData.told && !passiveMidasData.firstNoticedPassive) {
    // Set the time when passive midas was first noticed
    await redisClient.setJson(`${token}:passiveMidas`, {
      ...passiveMidasData,
      firstNoticedPassive: currentTime,
    })
    return false
  }
  if (
    midasCharges === 2 &&
    currentTime - passiveMidasData.firstNoticedPassive > passiveMidasThreshold &&
    !passiveMidasData.told
  ) {
    // Set the time when passive midas was told to chat
    await redisClient.setJson(`${token}:passiveMidas`, {
      ...passiveMidasData,
      told: currentTime,
    })
    return true
  }
  if (midasCharges !== 2 && passiveMidasData.told) {
    // Calculate the time taken to use midas after being passive
    const secondsToUse = Math.round(
      (Date.now() - passiveMidasData.told + passiveMidasThreshold) / 1000
    )
    // Reset passive midas data
    await resetPassiveTime(token)
    return secondsToUse
  }
  if (midasCharges !== 2) {
    // Reset passive midas data
    await resetPassiveTime(token)
    return false
  }

  return false
}

function checkWashProfanity(text: string): {
  detected: boolean
  locale?: string
  matchingWords?: string[]
} {
  for (const locale of supportedLocales) {
    if (wash.check(locale, text)) {
      // Get the actual words for diagnostic purposes
      const wordList = wash.words(locale)

      // The actual words that matched using washyourmouthoutwithsoap's tokenize method
      const tokens = new Set(
        text
          .toLowerCase()
          .replaceAll(/[\s+]+/g, ' ')
          .replace('/ {2,}/', ' ')
          .split(' ')
          .concat(
            text
              .toLowerCase()
              .replaceAll(/[^\w\s]/g, '')
              .replace('/ {2,}/', ' ')
              .split(' ')
          )
      )

      const matchingWords = wordList.filter((word: string) => tokens.has(word.toLowerCase()))

      return {
        detected: true,
        locale,
        matchingWords: matchingWords.length > 0 ? matchingWords : undefined,
      }
    }
  }

  return { detected: false }
}

