async (providerAccountId: string, text: string, reply_parent_message_id?: string) => {
          try {
            // Check if bot is banned before attempting to send message
            const isBanned = await checkBotStatus()
            if (isBanned) {
              return
            }

            const response = await sendTwitchChatMessage({
              broadcaster_id: providerAccountId,
              message: text || "I'm sorry, I can't do that",
              reply_parent_message_id,
              sender_id: process.env.TWITCH_BOT_PROVIDERID!,
            })

            // Only disable if message failed to send
            if (!response.data?.[0]?.is_sent) {
              const dropReason = response.data?.[0]?.drop_reason

              // Handle different drop reason codes that require disabling
              if (dropReason?.code === 'followers_only_mode') {
                await disableUser(providerAccountId, dropReason)
              } else if (dropReason?.code === 'user_warned') {
                await disableUser(providerAccountId, dropReason)
              } else if (dropReason?.code === 'banned_phone_alias') {
                // Bot's phone number is banned from the channel - this should disable the bot
                await disableUser(providerAccountId, dropReason)
              } else if (dropReason?.code === 'rate_limited') {
                // Don't disable for rate limiting - just log it
                logger.warn('Chat message rate limited, not disabling account:', {
                  broadcaster_id: providerAccountId,
                  drop_reason: dropReason,
                  message: text,
                })
              } else if (dropReason?.code === 'send_error') {
                // Don't disable for generic send errors - just log them
                logger.error('Chat message send error, not disabling account:', {
                  broadcaster_id: providerAccountId,
                  drop_reason: dropReason,
                  message: text,
                })
              } else if (dropReason?.code === 'msg_rejected') {
                // Don't disable for message moderation - bot can still send other messages
                logger.warn('Chat message rejected by moderators, not disabling account:', {
                  broadcaster_id: providerAccountId,
                  drop_reason: dropReason,
                  message: text,
                })
              } else if (dropReason?.code === 'duplicate_message') {
                // Don't disable for duplicate messages - can retry later
                logger.warn('Chat message dropped as duplicate, not disabling account:', {
                  broadcaster_id: providerAccountId,
                  drop_reason: dropReason,
                  message: text,
                })
              } else if (dropReason?.code === 'msg_duplicate') {
                // Don't disable for Twitch's 30-second duplicate restriction
                logger.warn(
                  'Chat message blocked by Twitch duplicate restriction, not disabling account:',
                  {
                    broadcaster_id: providerAccountId,
                    drop_reason: dropReason,
                    message: text,
                  }
                )
              } else if (dropReason?.code) {
                // Only disable for actual permission issues
                await disableUser(providerAccountId, dropReason)
              } else {
                // Log the entire message and response for unknown issues
                logger.error('Failed to send chat message in drop reason:', {
                  broadcaster_id: providerAccountId,
                  drop_reason: dropReason,
                  message: text,
                  response,
                })
              }
            }
          } catch (error) {
            logger.error('Failed to send chat message in say', error)
          }
        }

function handleNewEvents(data: Packet, dotaClient: GSIHandlerType) {
  // Deduped against already-seen events by `${game_time}-${event_type}`.
  const newEvents = selectNewEvents(dotaClient.events, data.events)

  if (newEvents.length) {
    // Merge new and existing events
    dotaClient.events = [...dotaClient.events, ...newEvents]

    // Emit events and log if necessary
    newEvents.forEach((event) => {
      const rawData = event.data
      let dataType: string | undefined
      let dataWasObject = false
      let dataWasJsonParsed = false

      if (typeof rawData === 'string') {
        try {
          const parsedData = JSON.parse(rawData) as { type?: unknown }
          if (typeof parsedData?.type === 'string') {
            dataType = parsedData.type
          }
          dataWasJsonParsed = true
        } catch {
          // Ignore malformed data payloads
        }
      } else if (rawData && typeof rawData === 'object') {
        dataWasObject = true
        // Use type assertion to allow access to 'type' property safely
        const potentialType = (rawData as { type?: unknown }).type
        if (typeof potentialType === 'string') {
          dataType = potentialType
        }
      }

      const shouldLogUnknownEventType = !validEventTypes.has(event.event_type)
      const shouldLogUnknownChatMessageType =
        typeof dataType === 'string' && !chatMessageTypesSet.has(dataType)
      const unknownDiagnosticKeys = [
        shouldLogUnknownEventType ? `event:${event.event_type}` : null,
        shouldLogUnknownChatMessageType ? `message:${dataType}` : null,
      ].filter((key): key is string => key !== null)
      const shouldLogDiagnostic = unknownDiagnosticKeys
        .map((key) => shouldLogUnknownGsiEvent(key))
        .some(Boolean)

      events.emit(`event:${event.event_type}`, event, dotaClient.client.token)
      if (shouldLogDiagnostic) {
        logger.info('[NEWEVENT]', {
          dataWasJsonParsed,
          dataWasObject,
          event,
          unknownDiagnosticKeys,
        })
      }
    })
  }
}

async function lookupLeaderRank(mmr: number, steam32Id?: number | null): Promise<LeaderRankData> {
  const lowestLeaderRank = leaderRanks.at(-1)
  if (!lowestLeaderRank) {
    throw new Error('Leader ranks must not be empty')
  }
  const defaultNotFound: LeaderRankData = {
    mmr,
    myRank: lowestLeaderRank,
    standing: null,
  }

  // Return default values if steam32Id is undefined or null
  if (!steam32Id) {
    return defaultNotFound
  }

  const cacheKey = `${steam32Id}:medal`
  let result: LeaderRankData

  const redisClient = RedisClient.getInstance()
  // Try to get the cached result first
  const medalCache = await redisClient.getJson<LeaderRankData>(cacheKey)
  if (medalCache) {
    result = medalCache
  } else {
    try {
      const getCardPromise = new Promise<Cards>((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          reject(new CustomError(t('matchData8500', { emote: 'PoroSad', lng: 'en' })))
        }, 10_000) // 5 second timeout

        steamSocket.emit('getCard', steam32Id, (err: unknown, card: Cards) => {
          clearTimeout(timeoutId)
          if (err) {
            reject(err)
          } else {
            resolve(card)
          }
        })
      })

      // Fetch the leaderboard rank from the Dota 2 server
      const data = await getCardPromise
      const standing: number = data?.leaderboard_rank

      // If the rank is not available, return default values
      if (!standing || typeof standing !== 'number') {
        return defaultNotFound
      }

      // Find the corresponding leaderboard rank for the given standing
      const myRank = leaderRanks.find((rank) => standing <= rank.range[1]) ?? lowestLeaderRank

      // Construct the result object
      result = { mmr, myRank, standing }

      // Cache the result
      await redisClient.setJson(cacheKey, result)
    } catch {
      return defaultNotFound
    }
  }

  return result
}

