function handleSocketAuth(socket: Socket, next: (err?: Error) => void) {
  const { client: clientType, token, twitchId } = socket.handshake.auth
  const lookup =
    clientType === WIN_LOSS_PROFILE_CLIENT_TYPE && typeof twitchId === 'string'
      ? { twitchId }
      : { token }

  const authenticate = (attempt = 0) => {
    getDBUser(lookup)
      .then(({ reason, result: client }) => {
        if (client?.token) {
          socket.data.clientType = clientType
          socket.data.dotabodClient = client
          next()
          return
        }

        if (reason === 'Token is currently being looked up' && attempt < 20) {
          setTimeout(() => {
            authenticate(attempt + 1)
          }, 100)
          return
        }

        socket.emit('auth_error', 'Invalid token')
        socket.disconnect(true)
      })
      .catch((error) => {
        logger.info('[GSI] Error checking auth', { error, token, twitchId })
        socket.emit('auth_error', 'Authentication error')
        socket.disconnect(true)
      })
  }

  authenticate()
}

function truncateToLimit(message: string, locale: string, maxLength: number): string {
  if (isWithinTranslatedLimit(message, locale, maxLength)) {
    return message
  }

  let left = 0
  let right = message.length
  let best = ''

  while (left <= right) {
    const mid = Math.floor((left + right) / 2)
    const candidate = `${message.slice(0, mid)}${TRUNCATION_SUFFIX}`

    if (isWithinTranslatedLimit(candidate, locale, maxLength)) {
      best = candidate
      left = mid + 1
    } else {
      right = mid - 1
    }
  }

  if (best) {
    return best
  }

  return isWithinTranslatedLimit(TRUNCATION_SUFFIX, locale, maxLength) ? TRUNCATION_SUFFIX : ''
}

