async function getRankDescription({
  locale,
  mmr,
  steam32Id,
  showRankMmr = true,
}: RankDescription) {
  const rankResponse = await getRankDetail(mmr, steam32Id)

  if (!rankResponse) {
    return null
  }

  if ('standing' in rankResponse) {
    const rankTitle = 'Immortal'
    const standing = rankResponse.standing && `#${rankResponse.standing}`
    const msgs: string[] = []

    if (showRankMmr) {
      msgs.push(`${mmr} MMR`)
    }
    msgs.push(rankTitle)
    if (standing) {
      msgs.push(standing)
    }

    return msgs.join(' · ')
  }

  const { myRank, nextMMR, mmrToNextRank, winsToNextRank } = rankResponse

  if (!showRankMmr) {
    return myRank.title
  }

  const count = mmrToNextRank <= MULTIPLIER_SOLO ? 1 : winsToNextRank
  const nextAt = t('rank.nextRankAt', { lng: locale })
  const nextIn = t('rank.nextRankIn', {
    count,
    emote: 'peepoClap',
    lng: locale,
  })

  const msgs: string[] = []
  msgs.push(String(mmr), myRank.title, `${nextAt} ${nextMMR}${count === 1 ? '' : ` ${nextIn}`}`)
  if (count === 1) {
    msgs.push(nextIn)
  }

  return msgs.join(' · ')
}

