async function disableUser(
  providerAccountId: string,
  dropReason?: { code: string; message: string }
) {
  const { data: user } = await supabase
    .from('accounts')
    .select('userId')
    .eq('providerAccountId', providerAccountId)
    .single()

  if (!user?.userId) {
    logger.error('Failed to send chat message: no user found', providerAccountId)
    return
  }

  // Check if we've already disabled this user recently to prevent duplicate calls
  const cacheKey = `${user.userId}:${dropReason?.code || 'unknown'}`
  const cached = disableUserCache.get(cacheKey)
  const now = Date.now()

  if (cached && now - cached.timestamp < DISABLE_CACHE_EXPIRY) {
    logger.info('[DISABLE_CACHE] Skipping duplicate disable call', {
      cachedAt: new Date(cached.timestamp).toISOString(),
      dropReason: dropReason?.code,
      providerAccountId,
      userId: user.userId,
    })
    return
  }

  // Add to cache to prevent duplicates
  disableUserCache.set(cacheKey, {
    dropReason: dropReason?.code || 'unknown',
    providerAccountId,
    timestamp: now,
  })

  // Clean up expired cache entries
  for (const [key, value] of disableUserCache.entries()) {
    if (now - value.timestamp >= DISABLE_CACHE_EXPIRY) {
      disableUserCache.delete(key)
    }
  }

  // Create metadata based on the drop reason
  let metadata: DisableReasonMetadata = {
    drop_reason: dropReason?.code || 'unknown',
    drop_reason_message: dropReason?.message || 'Unknown chat permission issue',
  }

  // Add specific details based on drop reason code
  switch (dropReason?.code) {
    case 'followers_only_mode': {
      metadata = {
        ...metadata,
        additional_info: 'Bot is not a moderator and channel has followers-only mode enabled',
        permission_required: 'moderator',
      }
      break
    }
    case 'user_warned': {
      metadata = {
        ...metadata,
        additional_info:
          'Bot account is currently warned and cannot send messages until warning is acknowledged',
        warning_status: 'active',
      }
      break
    }
    default: {
      metadata = {
        ...metadata,
        additional_info: `Chat message blocked due to: ${dropReason?.message || 'Unknown reason'}`,
      }
      break
    }
  }

  await commandDisable.disable(user.userId, 'CHAT_PERMISSION_DENIED', metadata)

  logger.error('Failed to send chat message. Disabled user', {
    dropReason: dropReason?.code,
    dropReasonMessage: dropReason?.message,
    providerAccountId,
  })
}

async function saveMatchData(client: SocketClient) {
  // This now waits for the bet to complete before checking match data
  // Since match data is delayed it will run far fewer than before, when checking actual match id of an ingame match
  // the matchid is saved when the hero is selected
  const matchId = await redisClient.client.get(`${client.token}:matchId`)
  if (!matchId || !Number(matchId)) {
    return
  }

  if (!client.steam32Id) {
    return
  }

  // Check for account sharing before proceeding with match data processing
  const accountSharingDetected = await checkAccountSharing(client, matchId)
  if (accountSharingDetected) {
    // If account sharing is detected, stop processing for this client
    return
  }

  const cacheKey = `${matchId}:${client.token}`

  // Check in-memory cache first
  const cachedData = matchDataCache.get(cacheKey)
  if (cachedData) {
    // If cache is still valid, use cached data and return
    if (Date.now() - cachedData.timestamp < CACHE_EXPIRATION) {
      if (cachedData.steamServerId && cachedData.lobbyType !== null) {
        return
      }
    } else {
      // If cache expired, remove it
      matchDataCache.delete(cacheKey)
    }
  }

  // Implement debounce logic
  const debounceKey = client.token
  const now = Date.now()
  const debounceData = saveMatchDataDebounceMap.get(debounceKey)

  // If this client's function is already in progress or ran recently, skip this execution
  if (debounceData) {
    if (debounceData.inProgress || now - debounceData.lastExecuted < DEBOUNCE_INTERVAL) {
      return
    }
  }

  // Mark this execution as in progress
  saveMatchDataDebounceMap.set(debounceKey, { inProgress: true, lastExecuted: now })

  try {
    // did we already come here before?
    const res = await redisClient.client
      .multi()
      .get(`${matchId}:${client.token}:steamServerId`)
      .get(`${matchId}:${client.token}:lobbyType`)
      .exec()

    const [steamServerId] = res
    const [, lobbyType] = res

    // Update cache with Redis data
    matchDataCache.set(cacheKey, {
      lobbyType: lobbyType ? String(lobbyType) : null,
      steamServerId: steamServerId ? String(steamServerId) : null,
      timestamp: now,
    })

    if (steamServerId && lobbyType !== null) {
      return
    }

    // PRESERVED — gated, not dead. This block is the sole writer of the redis steamServerId key
    // that the ordinary-pub `!items`/`!stats`/`!winprobability` fallback later reads. SourceTV
    // commands instead use the server_steam_id already present in delayedGames. This lookup stays
    // gated pending bot-friend management at scale; see memory `keep-spectate-friend-path`.
    if (
      !steamServerId &&
      lobbyType === null &&
      !is8500Plus(client) &&
      ENABLE_SPECTATE_FRIEND_GAME
    ) {
      // Fix: Check if we're already looking up this match to prevent race conditions
      if (steamServerLookupMap.has(matchId)) {
        return
      }

      // Add to lookup map before starting the async operation
      steamServerLookupMap.add(matchId)

      try {
        const getDelayedDataPromise = new Promise<string>((resolve, reject) => {
          const timeoutId = setTimeout(() => {
            reject(new CustomError(t('matchData8500', { emote: 'PoroSad', lng: client.locale })))
          }, 10_000) // 10 second timeout

          steamSocket.emit(
            'getUserSteamServer',
            client.steam32Id,
            (err: unknown, cards: string) => {
              clearTimeout(timeoutId)
              if (err) {
                reject(err)
              } else {
                resolve(cards)
              }
            }
          )
        })

        const steamServerId = await getDelayedDataPromise

        if (steamServerId) {
          await redisClient.client.set(
            `${matchId}:${client.token}:steamServerId`,
            steamServerId.toString()
          )

          // Update cache
          matchDataCache.set(cacheKey, {
            lobbyType: null,
            steamServerId: steamServerId.toString(),
            timestamp: Date.now(),
          })
        }
      } catch {
        // Do nothing, we don't want to log this error
        // logger.error('Error getting steam server data', { error, matchId })
      } finally {
        // Always remove from the map, even if there was an error
        steamServerLookupMap.delete(matchId)
      }
    }

    // Re-check steamServerId from cache first, then Redis if needed
    let currentSteamServerId = matchDataCache.get(cacheKey)?.steamServerId || null
    if (!currentSteamServerId) {
      currentSteamServerId = await redisClient.client.get(
        `${matchId}:${client.token}:steamServerId`
      )

      // Update cache if we found it in Redis
      if (currentSteamServerId) {
        const currentCache = matchDataCache.get(cacheKey) || {
          lobbyType: null,
          steamServerId: null,
          timestamp: now,
        }
        matchDataCache.set(cacheKey, {
          ...currentCache,
          steamServerId: currentSteamServerId,
          timestamp: now,
        })
      }
    }

    if (currentSteamServerId && lobbyType === null && !is8500Plus(client)) {
      // Fix: Check if we're already looking up this match to prevent race conditions
      if (steamDelayDataLookupMap.has(matchId)) {
        return
      }

      steamDelayDataLookupMap.add(matchId)

      try {
        const getDelayedDataPromise = new Promise<DelayedGames>((resolve, reject) => {
          const timeoutId = setTimeout(() => {
            reject(new CustomError(t('matchData8500', { emote: 'PoroSad', lng: client.locale })))
          }, 10_000) // 10 second timeout

          steamSocket.emit(
            'getRealTimeStats',
            {
              match_id: matchId,
              refetchCards: true,
              steam_server_id: currentSteamServerId.toString(),
              token: client.token,
            },
            (err: unknown, data: DelayedGames) => {
              clearTimeout(timeoutId)
              if (err) {
                reject(err)
              } else {
                resolve(data)
              }
            }
          )
        })

        const delayedData = await getDelayedDataPromise

        if (delayedData?.match && delayedData.match.lobby_type !== undefined) {
          await Promise.all([
            redisClient.client.set(
              `${matchId}:${client.token}:lobbyType`,
              delayedData.match.lobby_type
            ),
            redisClient.client.set(
              `${matchId}:${client.token}:gameMode`,
              delayedData.match.game_mode
            ),
          ])

          // Update cache with complete data
          matchDataCache.set(cacheKey, {
            lobbyType: String(delayedData.match.lobby_type),
            steamServerId: currentSteamServerId.toString(),
            timestamp: Date.now(),
          })
        }
      } catch (error) {
        if (!(error instanceof CustomError)) {
          logger.error('Error getting delayed match data', { error, matchId })
        }
      } finally {
        // Always remove from the map, even if there was an error
        steamDelayDataLookupMap.delete(matchId)
      }
    }
  } finally {
    // Update the debounce map to mark execution as complete
    const currentDebounce = saveMatchDataDebounceMap.get(debounceKey)
    if (currentDebounce) {
      saveMatchDataDebounceMap.set(debounceKey, { ...currentDebounce, inProgress: false })

      // Set up an automatic cleanup for the debounce map entry after 5 minutes of inactivity
      setTimeout(() => {
        const entry = saveMatchDataDebounceMap.get(debounceKey)
        if (entry && Date.now() - entry.lastExecuted > 300_000) {
          // 5 minutes
          saveMatchDataDebounceMap.delete(debounceKey)
        }
      }, 300_000) // 5 minutes
    }
  }
}

function formatTranslatedSpeakerLabel(
  heroName: string,
  playerId: number,
  locale: string
): string {
  const fallbackSpeakerLabels = new Set([
    t('chatTranslation.legacyHeroLabel', {
      lng: locale,
      playerId,
    }),
    `${playerId}`,
  ])
  if (fallbackSpeakerLabels.has(heroName)) {
    // No hero resolved — use a neutral label. Never expose the numeric player_id
    // here: it's 0-indexed (off-by-one from the 1-10 top bar) and reshuffled at
    // 8500+, so "Player 9" would wrongly imply the 9th-slot / Green player.
    return t('chatTranslation.unknownPlayer', { lng: locale })
  }
  // Hero resolved — show only the name. Deliberately omit a "(P9)" player_id
  // suffix: player_id is 0-indexed (off-by-one from the 1-10 top bar) and
  // reshuffled at 8500+, so it would mislead viewers about slot/color.
  return heroName
}

