function processUnmarkedKillListChanges(
  req: Request,
  _res: Response,
  next: NextFunction
): void {
  const token = req.body?.auth?.token as string | undefined
  const handler = token ? gsiHandlers.get(token) : undefined
  const current = req.body?.player?.kill_list

  if (!handler || !isPlayingMatch(req.body) || !current || typeof current !== 'object') {
    next()
    return
  }

  const matchId = String(req.body?.map?.matchid ?? '')
  const previous = killListSnapshots.get(handler)
  const currentValues = Object.fromEntries(
    Object.entries(current).filter(
      (entry): entry is [string, number] => typeof entry[1] === 'number'
    )
  )

  killListSnapshots.set(handler, { matchId, values: currentValues })

  if (!previous || previous.matchId !== matchId) {
    next()
    return
  }

  const markedKeys = getKillListDeltaKeys(req.body)
  const unmarkedIncreases = Object.fromEntries(
    Object.entries(currentValues).filter(
      ([key, value]) => !markedKeys.has(key) && value > (previous.values[key] ?? 0)
    )
  )

  if (Object.keys(unmarkedIncreases).length > 0) {
    events.emit('player:kill_list', unmarkedIncreases, token)
  }

  next()
}

function pickCandidate(
  channelId: string,
  candidates: readonly string[],
  settings: MessageType['channel']['settings'],
  subscription: MessageType['channel']['client']['subscription']
): string | null {
  const recent = lastSuggested.get(channelId)
  const now = Date.now()
  for (const candidate of candidates) {
    if (recent && recent.cmd === candidate && now - recent.ts < REPEAT_WINDOW_MS) {
      continue
    }
    const dbkey = commandHandler.commands.get(candidate)?.dbkey
    if (dbkey && !getValueOrDefault(dbkey, settings, subscription)) {
      continue
    }
    return candidate
  }
  return null
}

